def countReachableStrings(s, pairs):
    MOD = 1000000007
    n = len(s)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in pairs:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv = [1] * (n + 1)
    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv[i - 1] = inv[i] * i % MOD
    groups = {}
    for i in range(n):
        g = groups.setdefault(find(i), {})
        g[s[i]] = g.get(s[i], 0) + 1
    res = 1
    for g in groups.values():
        k = sum(g.values())
        ways = fact[k]
        for c in g.values():
            ways = ways * inv[c] % MOD
        res = res * ways % MOD
    return res
